<span class="line">  rest<span class="token punctuation">.</span>RseRestUssApi<span class="token punctuation">.</span><span class="token function">registerApi</span><span class="token punctuation">(</span>importedApi<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
