<span class="line">  <span class="token keyword">const</span> mvsApi<span class="token operator">:</span> MainframeInteraction<span class="token punctuation">.</span>IMvs <span class="token operator">=</span> ZoweSettings<span class="token punctuation">.</span><span class="token function">getZoweExplorerApi</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getMvsApi</span><span class="token punctuation">(</span>loadedProfile<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
